namespace Fanex.Age.Utility.ResourceUtil
{
    public class CardImages
    {
        private string _path;

        public CardImages()
        {
            Page page = (Page)HttpContext.Current.Handler;
            _path = page.ResolveUrl("~/img/Poker/");
        }

        public string GetCardUrl(string cardNo)
        {
            return _path + cardNo + ".jpg";
        }

        public string CreateImageTag(string cardNo)
        {
            return string.Format("<img alt='{0}' src='{1}' />", cardNo, GetCardUrl(cardNo));
        }
    }
}
